{{-- Der Umkreis. Steht immer im Markup und wird nur ein- und ausgeblendet: So
     kann der Schieberegler den Radius veraendern, ohne dass bei jedem Zug ein
     Element entsteht. --}}
<g class="germany-map__area" data-germany-map-area @unless ($showArea ?? false) hidden @endunless>
    <circle class="germany-map__circle" data-germany-map-circle cx="{{ $mapX ?? 0 }}" cy="{{ $mapY ?? 0 }}" r="{{ $mapRadius ?? 0 }}" />
    <circle class="germany-map__pin" data-germany-map-pin cx="{{ $mapX ?? 0 }}" cy="{{ $mapY ?? 0 }}" r="5" />
</g>
